double _accuracy(MlService ml, Map<String, List<String>> set) {
  int ok = 0;
  int total = 0;
  set.forEach((String label, List<String> items) {
    for (final String item in items) {
      total++;
      if (ml.classify(item).categoryName == label) ok++;
    }
  });
  return ok / total;
}

void main() {
  late MlService ml;

  setUpAll(() async {
    ml = MlService();
    await ml.initialize();
  });

  test('model memiliki 15 kategori', () {
    expect(ml.categories.length, 15);
  });

  test('akurasi pada kumpulan uji standar minimal 95%', () {
    expect(_accuracy(ml, _testSet), greaterThanOrEqualTo(0.95));
  });

  test('akurasi pada kumpulan uji sulit minimal 90%', () {
    expect(_accuracy(ml, _hardSet), greaterThanOrEqualTo(0.90));
  });

  test('akurasi pada kumpulan uji baru minimal 93%', () {
    expect(_accuracy(ml, _freshSet), greaterThanOrEqualTo(0.93));
  });

  test('akurasi pada teks salah baca OCR minimal 85%', () {
    expect(_accuracy(ml, _ocrNoiseSet), greaterThanOrEqualTo(0.85));
  });

  test('barang pada struk elektronik masuk kategori Elektronik', () {
    for (final String item in <String>['PPG', 'Pulse Sensor', 'Pointer']) {
      expect(ml.classify(item).categoryName, 'Elektronik', reason: item);
    }
  });
}
